import pandas as pd
import numpy as np
import base64

# Load data and compute metrics for the HTML report
df = pd.read_csv('benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], format='%m/%d/%Y')
df = df.sort_values('Date').reset_index(drop=True)
df['DailyReturn'] = df['Close'].pct_change()
df['MA50'] = df['Close'].rolling(50).mean()
df['MA200'] = df['Close'].rolling(200).mean()

running_max = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - running_max) / running_max * 100
df['RollVol30'] = df['DailyReturn'].rolling(30).std() * np.sqrt(252) * 100
df['DailyRange'] = (df['High'] - df['Low']) / df['Close'] * 100

# KPIs
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
cumulative_return = (last_close / first_close - 1)
years = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days / 365.25
cagr = ((last_close / first_close) ** (1/years) - 1)
annualized_vol = df['DailyReturn'].std() * np.sqrt(252)
max_drawdown = df['Drawdown'].min() / 100
avg_volume = df['Volume'].mean()

# ATH/ATL
ath_idx = df['Close'].idxmax()
atl_idx = df['Close'].idxmin()
ath_price = df.loc[ath_idx, 'Close']
ath_date = df.loc[ath_idx, 'Date'].strftime('%B %d, %Y')
atl_price = df.loc[atl_idx, 'Close']
atl_date = df.loc[atl_idx, 'Date'].strftime('%B %d, %Y')

# Yearly returns
yearly = df.groupby(df['Date'].dt.year).agg(First=('Close', 'first'), Last=('Close', 'last'))
yearly['Return'] = (yearly['Last'] / yearly['First'] - 1)
best_year = yearly['Return'].idxmax()
worst_year = yearly['Return'].idxmin()
best_return = yearly.loc[best_year, 'Return']
worst_return = yearly.loc[worst_year, 'Return']
positive_years = (yearly['Return'] > 0).sum()
total_years = len(yearly)

# Decades
decades = {}
for decade in [2000, 2010, 2020]:
    decade_df = df[(df['Date'].dt.year >= decade) & (df['Date'].dt.year < decade + 10)]
    d_first = decade_df['Close'].iloc[0]
    d_last = decade_df['Close'].iloc[-1]
    d_years = (decade_df['Date'].iloc[-1] - decade_df['Date'].iloc[0]).days / 365.25
    d_cagr = ((d_last / d_first) ** (1 / max(d_years, 0.1)) - 1)
    decades[decade] = {'first': d_first, 'last': d_last, 'cagr': d_cagr}

# Volume context
df['VolumeMA50'] = df['Volume'].rolling(50).mean()
df['VolumeStd50'] = df['Volume'].rolling(50).std()
df['VolumeZ'] = (df['Volume'] - df['VolumeMA50']) / df['VolumeStd50']
spikes = df[df['VolumeZ'] > 3].copy()

# Major drawdown episodes (>30%)
def find_major_drawdowns(df, threshold=-0.30):
    episodes = []
    in_drawdown = False
    peak_idx = None
    trough_idx = None
    for i in range(len(df)):
        if not in_drawdown:
            if df['Drawdown'].iloc[i] <= threshold * 100:
                in_drawdown = True
                peak_idx = df.loc[:i, 'Close'].idxmax()
                trough_idx = i
        else:
            if df['Close'].iloc[i] < df['Close'].iloc[trough_idx]:
                trough_idx = i
            if df['Close'].iloc[i] >= df.loc[peak_idx, 'Close']:
                in_drawdown = False
                episodes.append({
                    'peak_date': df.loc[peak_idx, 'Date'].strftime('%B %d, %Y'),
                    'trough_date': df.loc[trough_idx, 'Date'].strftime('%B %d, %Y'),
                    'recovery_date': df.loc[i, 'Date'].strftime('%B %d, %Y'),
                    'peak_price': df.loc[peak_idx, 'Close'],
                    'trough_price': df.loc[trough_idx, 'Close'],
                    'drawdown_pct': (df.loc[trough_idx, 'Close'] / df.loc[peak_idx, 'Close'] - 1),
                    'trough_to_recovery_days': (df.loc[i, 'Date'] - df.loc[trough_idx, 'Date']).days,
                    'peak_to_recovery_days': (df.loc[i, 'Date'] - df.loc[peak_idx, 'Date']).days
                })
    if in_drawdown:
        episodes.append({
            'peak_date': df.loc[peak_idx, 'Date'].strftime('%B %d, %Y'),
            'trough_date': df.loc[trough_idx, 'Date'].strftime('%B %d, %Y'),
            'recovery_date': 'Ongoing',
            'peak_price': df.loc[peak_idx, 'Close'],
            'trough_price': df.loc[trough_idx, 'Close'],
            'drawdown_pct': (df.loc[trough_idx, 'Close'] / df.loc[peak_idx, 'Close'] - 1),
            'trough_to_recovery_days': 'N/A',
            'peak_to_recovery_days': (df['Date'].iloc[-1] - df.loc[peak_idx, 'Date']).days
        })
    return episodes

episodes = find_major_drawdowns(df, threshold=-0.30)

# Significant 20-30% drawdowns
episodes_20 = find_major_drawdowns(df, threshold=-0.20)
major_peaks = {e['peak_date'] for e in episodes}
episodes_20_unique = [e for e in episodes_20 if e['peak_date'] not in major_peaks]

# Sharpe-like
sharpe = cagr / annualized_vol

# Max daily gain/loss
max_gain = df['DailyReturn'].max()
max_loss = df['DailyReturn'].min()
max_gain_date = df.loc[df['DailyReturn'].idxmax(), 'Date'].strftime('%B %d, %Y')
max_loss_date = df.loc[df['DailyReturn'].idxmin(), 'Date'].strftime('%B %d, %Y')

# GFC and COVID lows
