for start, end, label in [(2000, 2005, '2000–2004'), (2005, 2010, '2005–2009'), (2010, 2015, '2010–2014'), (2015, 2020, '2015–2019'), (2020, 2026, '2020–2026')]:
    era = df[(df['Date'].dt.year >= start) & (df['Date'].dt.year < end)]
    vol_eras[label] = era['Volume'].mean()

# Daily range by era
range_eras = {}
for start, end, label in [(2000, 2005, '2000–2004'), (2005, 2010, '2005–2009'), (2010, 2015, '2010–2014'), (2015, 2020, '2015–2019'), (2020, 2026, '2020–2026')]:
    era = df[(df['Date'].dt.year >= start) & (df['Date'].dt.year < end)]
    range_eras[label] = era['DailyRange'].mean()

# Read chart images
charts = {}
for name in ['price_trend', 'drawdown', 'volatility', 'volume', 'annual_returns', 'daily_range']:
    with open(f'output/charts/{name}.png', 'rb') as f:
